    if(q.concept==='dopamine')return /prolactin|breast discharge|galactorrhea/.test(q.stem.toLowerCase())?'dopamine-prolactin':/aims/.test(q.stem.toLowerCase())?'tardive-monitoring':'movement-effects';
    if(q.concept==='ssri')return /citalopram|qt-/.test(q.stem.toLowerCase())?'ssri-qt':/three days|taken.*days/.test(q.stem.toLowerCase())?'ssri-onset':'serotonin-toxicity';
    return q.concept;
