  function referenceText(s){return String(s)
    .replace(/Herbals aren’t FDA regulated/g,'Supplements are regulated differently from prescription medicines')
    .replace(/no sexual side effects|no sexual dysfunction/gi,'often fewer sexual adverse effects')
    .replace(/\*\*eating disorders\*\*/g,'**current or prior anorexia or bulimia**')
    .replace(/\bseizures and eating disorders\b/g,'seizure disorder and current or prior anorexia or bulimia')
    .replace(/\bavoid in eating disorders\b/gi,'avoid with current or prior anorexia or bulimia')
    .replace(/so (?:the lamotrigine dose is halved|halve the dose|the lamotrigine dose is cut in half)/gi,'so verify the interaction-specific prescribed titration and dose')
    .replace(/\(give \*\*early in the day\*\*\)/g,'(follow the prescribed formulation’s timing)')
    .replace(/give \*\*early in the day\*\*/g,'follow the prescribed formulation’s timing');}
  function referenceCard(card,topic){var x={h:card.h,b:card.b.map(referenceText),why:card.why,tag:card.tag};
    if(topic==='neuro'&&card.h==='The HPA axis and stress')x.b[1]='HPA/cortisol findings vary by condition and individual; they are associations, not a stand-alone diagnostic test for depression or PTSD.';
    if((topic==='legal'||topic==='ch6')&&card.h==='Restraint and seclusion')x.b=[find('restraints').mechanism,find('restraints').cues,find('restraints').action,find('restraints').evaluate,'Seclusion means involuntary isolation with exit prevented. A voluntary break the patient is free to leave is different. A medication is a restraint under the federal definition when used to restrict behavior/movement and it is not standard treatment/dosage for the condition.'];
    if(topic==='legal'&&card.h==='Patients’ rights')x.b=['Patients retain dignity, privacy, communication, treatment participation and the right to appropriate legal processes.','Involuntary admission does not by itself remove decision-making capacity or authorize all treatment over objection. Emergency authority and other exceptions follow the applicable law.','Informed consent requires understanding and voluntariness, not just a signature. Psychiatric advance directives can record preferences while the person can decide.'];
    return x;}
